//! Multimodal multi-study knowledge-representation inference engine.
//! Atlas feature: `AFA-brain-P04-F02`.

use bioprism_foundation::{AutonomyTier, CapabilityManifest, Determinism, Effect, EvidenceReference, EvidenceState, ResearchSurface, TypedPort, TypedResearchArtifact, PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::{BTreeMap, BTreeSet};
use thiserror::Error;

pub const FEATURE_ID: &str = "AFA-brain-P04-F02";
pub const CONTRACT_VERSION: &str = "brain-multimodal-knowledge-representation-inference-engine/1.0";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct MultimodalKnowledgeClaim { pub claim_id: String, pub study_id: String, pub modality: String, pub semantic_profile: String, pub subject: String, pub predicate: String, pub object: String, pub evidence_digest: Option<ContentHash>, pub provenance_digest: Option<ContentHash>, pub comparable: bool, pub state: EvidenceState, pub boundary: String }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct MultimodalKnowledgeRequest { pub request_id: String, pub claims: Vec<MultimodalKnowledgeClaim>, pub required_studies: Vec<String>, pub required_modalities: Vec<String>, pub replay_identity: ContentHash, pub policy_allow: bool, pub protected_closure: bool, pub raw_data_local: bool, pub boundary: String }
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum MultimodalKnowledgeDisposition { Completed, Partial, Unresolved, Denied }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct MultimodalKnowledgeReceipt { pub schema_version: String, pub contract_version: String, pub feature_id: String, pub request_id: String, pub disposition: MultimodalKnowledgeDisposition, pub candidate_order: Vec<String>, pub admitted_order: Vec<String>, pub unresolved_order: Vec<String>, pub denied_order: Vec<String>, pub study_order: Vec<String>, pub modality_order: Vec<String>, pub coverage_order: Vec<String>, pub comparability_order: Vec<String>, pub world_digest: ContentHash, pub evidence_digest: ContentHash, pub provenance_digest: ContentHash, pub replay_identity: ContentHash, pub witness_order: Vec<String>, pub counterexample_order: Vec<String>, pub omissions: Vec<String>, pub uncertainty: Vec<String>, pub negative_evidence: Vec<String>, pub effect_receipts: Vec<String>, pub artifact: TypedResearchArtifact, pub raw_data_local: bool, pub boundary: String }
#[derive(Debug, Error, PartialEq, Eq)]
pub enum MultimodalKnowledgeError { #[error("invalid multimodal knowledge request: {0}")] Invalid(String), #[error("multimodal knowledge artifact failed: {0}")] Artifact(String) }

impl MultimodalKnowledgeReceipt { pub fn validate(&self) -> Result<(), MultimodalKnowledgeError> { if self.schema_version != RESEARCH_CONTRACT_SCHEMA_VERSION || self.contract_version != CONTRACT_VERSION || self.feature_id != FEATURE_ID || self.boundary != PRECLINICAL_BOUNDARY || !self.raw_data_local || self.request_id.trim().is_empty() || self.candidate_order.is_empty() || self.study_order.len() < 2 || self.modality_order.len() < 2 || self.effect_receipts.is_empty() { return Err(MultimodalKnowledgeError::Invalid("multimodal knowledge identity, coverage, locality, or effects are incomplete".into())); } for values in [&self.candidate_order, &self.admitted_order, &self.unresolved_order, &self.denied_order, &self.study_order, &self.modality_order, &self.coverage_order, &self.comparability_order, &self.witness_order, &self.counterexample_order, &self.omissions, &self.uncertainty, &self.negative_evidence, &self.effect_receipts] { if values.windows(2).any(|pair| pair[0] >= pair[1]) { return Err(MultimodalKnowledgeError::Invalid("multimodal knowledge ordering is not canonical".into())); } } let classified = self.admitted_order.iter().chain(self.unresolved_order.iter()).chain(self.denied_order.iter()).cloned().collect::<BTreeSet<_>>(); if classified.len() != self.candidate_order.len() || classified.iter().any(|claim| !self.candidate_order.contains(claim)) { return Err(MultimodalKnowledgeError::Invalid("multimodal knowledge states do not partition claims".into())); } for digest in [&self.world_digest, &self.evidence_digest, &self.provenance_digest, &self.replay_identity] { if digest.as_str().len() != 64 { return Err(MultimodalKnowledgeError::Invalid("multimodal knowledge digest is invalid".into())); } } if self.effect_receipts.iter().any(|effect| !effect.starts_with("read:local-multimodal-knowledge-world:") && effect != "block:unsafe-release") { return Err(MultimodalKnowledgeError::Invalid("multimodal knowledge effect is outside read-only gate".into())); } self.artifact.validate_metadata().map_err(|error| MultimodalKnowledgeError::Artifact(error.to_string())) } pub fn digest(&self) -> Result<ContentHash, MultimodalKnowledgeError> { self.validate()?; ContentHash::of_value(&serde_json::to_value(self).map_err(|error| MultimodalKnowledgeError::Artifact(error.to_string()))?).map_err(|error| MultimodalKnowledgeError::Artifact(error.to_string())) } }

pub fn multimodal_knowledge_representation_inference_engine_manifest() -> CapabilityManifest { CapabilityManifest { schema_version: RESEARCH_CONTRACT_SCHEMA_VERSION.into(), capability_id: FEATURE_ID.into(), version: CONTRACT_VERSION.into(), owner_crate: "brain".into(), consumers: ["agent developer".into(), "multimodal study curator".into()].into(), behavior: "deterministically compiles comparable claims across imaging and omics studies into a local typed knowledge world".into(), value: "prevents missing study or modality coverage and semantic incompatibility from becoming asserted multimodal knowledge".into(), inputs: vec![TypedPort { name: "multimodal_knowledge_request".into(), schema: "ScopedResearchClaims2@1".into(), required: true }], outputs: vec![TypedPort { name: "typed_multimodal_knowledge_world".into(), schema: "TypedKnowledgeWorld1@1".into(), required: true }], effects: [Effect::ReadLocalData, Effect::WriteLocalArtifact].into(), permissions: ["read:local-research-artifacts".into()].into(), determinism: Determinism::ByteStable, evidence: vec![EvidenceReference { source_id: "json-schema".into(), state: EvidenceState::Supported, locator: Some("https://json-schema.org/specification".into()) }], authority_requirements: Vec::new(), autonomy_tier: AutonomyTier::A1, surfaces: [ResearchSurface::Ui, ResearchSurface::Api, ResearchSurface::Sdk, ResearchSurface::Cli, ResearchSurface::McpTool, ResearchSurface::Operator].into(), boundary: PRECLINICAL_BOUNDARY.into() } }

pub fn infer_multimodal_knowledge_representation(request: &MultimodalKnowledgeRequest) -> Result<MultimodalKnowledgeReceipt, MultimodalKnowledgeError> {
    if request.request_id.trim().is_empty() || request.claims.is_empty() || request.required_studies.len() < 2 || request.required_modalities.len() < 2 || request.replay_identity.as_str().len() != 64 || !request.raw_data_local || request.boundary != PRECLINICAL_BOUNDARY { return Err(MultimodalKnowledgeError::Invalid("multimodal knowledge identity, coverage, replay, locality, or boundary is invalid".into())); }
    let mut claims = request.claims.clone(); claims.sort_by(|left, right| left.claim_id.cmp(&right.claim_id)); let candidate = claims.iter().map(|claim| claim.claim_id.clone()).collect::<Vec<_>>(); if candidate.windows(2).any(|pair| pair[0] == pair[1]) || candidate.iter().any(|value| value.trim().is_empty()) { return Err(MultimodalKnowledgeError::Invalid("multimodal claim identifiers must be unique and non-empty".into())); }
    let map = claims.iter().map(|claim| (claim.claim_id.clone(), claim)).collect::<BTreeMap<_, _>>(); let mut admitted = BTreeSet::new(); let mut unresolved = BTreeSet::new(); let mut denied = BTreeSet::new(); let mut studies = BTreeSet::new(); let mut modalities = BTreeSet::new(); let mut profiles = BTreeSet::new(); let mut facts = Vec::new(); let mut witnesses = BTreeSet::from(["gate:typed-multimodal-claims".to_string(), "gate:study-coverage".to_string(), "gate:modality-coverage".to_string(), "gate:comparability".to_string(), "gate:evidence-provenance".to_string(), "gate:locality".to_string()]); let mut counterexamples = BTreeSet::new(); let mut omissions = BTreeSet::new(); let mut uncertainty = BTreeSet::new(); let mut negative = BTreeSet::new();
    for claim_id in &candidate { let claim = map[claim_id]; if !request.policy_allow || !request.protected_closure || claim.boundary != PRECLINICAL_BOUNDARY { denied.insert(claim_id.clone()); counterexamples.insert(format!("counterexample:{}:policy-closure", claim_id)); } else if !claim.comparable || claim.semantic_profile.trim().is_empty() { denied.insert(claim_id.clone()); counterexamples.insert(format!("counterexample:{}:incomparable-semantic-profile", claim_id)); } else if claim.evidence_digest.is_none() || claim.provenance_digest.is_none() { unresolved.insert(claim_id.clone()); omissions.insert(format!("claim:{}:evidence-or-provenance-missing", claim_id)); } else if matches!(claim.state, EvidenceState::Unknown | EvidenceState::Speculative) { unresolved.insert(claim_id.clone()); uncertainty.insert(format!("claim:{}:unknown-not-asserted", claim_id)); } else if matches!(claim.state, EvidenceState::Contradicted) { denied.insert(claim_id.clone()); negative.insert(format!("claim:{}:contradicted", claim_id)); } else { admitted.insert(claim_id.clone()); studies.insert(claim.study_id.clone()); modalities.insert(claim.modality.clone()); profiles.insert(claim.semantic_profile.clone()); facts.push(json!({"claim_id": claim.claim_id, "study_id": claim.study_id, "modality": claim.modality, "semantic_profile": claim.semantic_profile, "subject": claim.subject, "predicate": claim.predicate, "object": claim.object, "evidence_digest": claim.evidence_digest, "provenance_digest": claim.provenance_digest})); } }
    for required in &request.required_studies { if !studies.contains(required) { omissions.insert(format!("study:{}:coverage-missing", required)); uncertainty.insert(format!("study:{}:unresolved", required)); } } for required in &request.required_modalities { if !modalities.contains(required) { omissions.insert(format!("modality:{}:coverage-missing", required)); uncertainty.insert(format!("modality:{}:unresolved", required)); } } if profiles.len() > 1 { denied.extend(admitted.iter().cloned()); admitted.clear(); counterexamples.insert("counterexample:semantic-profile-conflict".into()); } if !request.policy_allow { omissions.insert("control:policy-denied".into()); } if !request.protected_closure { omissions.insert("control:protected-closure-incomplete".into()); } if !unresolved.is_empty() || studies.len() < request.required_studies.len() || modalities.len() < request.required_modalities.len() { witnesses.insert("gate:coverage-omissions-retained".into()); } let coverage = request.required_studies.iter().chain(request.required_modalities.iter()).cloned().collect::<BTreeSet<_>>(); let comparability = profiles.into_iter().collect::<Vec<_>>(); let disposition = if !request.policy_allow || !request.protected_closure || (denied.len() == candidate.len()) { MultimodalKnowledgeDisposition::Denied } else if admitted.is_empty() { MultimodalKnowledgeDisposition::Unresolved } else if !unresolved.is_empty() || coverage.iter().any(|item| !studies.contains(item) && !modalities.contains(item)) || !denied.is_empty() { MultimodalKnowledgeDisposition::Partial } else { MultimodalKnowledgeDisposition::Completed };
    let mut report_studies = studies.clone(); report_studies.extend(request.required_studies.iter().cloned()); let mut report_modalities = modalities.clone(); report_modalities.extend(request.required_modalities.iter().cloned()); facts.sort_by(|left, right| left["claim_id"].as_str().cmp(&right["claim_id"].as_str())); let world = ContentHash::of_value(&json!({"facts": facts, "study_order": studies, "modality_order": modalities, "comparability_order": comparability})).map_err(|error| MultimodalKnowledgeError::Artifact(error.to_string()))?; let evidence = ContentHash::of_value(&json!({"candidate_order": candidate, "admitted_order": admitted, "unresolved_order": unresolved, "denied_order": denied})).map_err(|error| MultimodalKnowledgeError::Artifact(error.to_string()))?; let provenance = ContentHash::of_value(&json!({"request_id": request.request_id, "world_digest": world, "replay_identity": request.replay_identity})).map_err(|error| MultimodalKnowledgeError::Artifact(error.to_string()))?; let payload = json!({"schema_version": RESEARCH_CONTRACT_SCHEMA_VERSION, "contract_version": CONTRACT_VERSION, "feature_id": FEATURE_ID, "request_id": request.request_id, "disposition": disposition, "world_digest": world, "evidence_digest": evidence, "provenance_digest": provenance, "replay_identity": request.replay_identity, "boundary": PRECLINICAL_BOUNDARY}); let artifact = TypedResearchArtifact::from_payload(format!("brain-multimodal-knowledge-representation:{}", request.request_id), "application/vnd.aurora.multimodal-typed-knowledge-world+json", &payload, Vec::new(), Vec::new()).map_err(|error| MultimodalKnowledgeError::Artifact(error.to_string()))?; let receipt = MultimodalKnowledgeReceipt { schema_version: RESEARCH_CONTRACT_SCHEMA_VERSION.into(), contract_version: CONTRACT_VERSION.into(), feature_id: FEATURE_ID.into(), request_id: request.request_id.clone(), disposition, candidate_order: candidate, admitted_order: admitted.into_iter().collect(), unresolved_order: unresolved.into_iter().collect(), denied_order: denied.into_iter().collect(), study_order: report_studies.into_iter().collect(), modality_order: report_modalities.into_iter().collect(), coverage_order: coverage.into_iter().collect(), comparability_order: comparability, world_digest: world, evidence_digest: evidence, provenance_digest: provenance, replay_identity: request.replay_identity.clone(), witness_order: witnesses.into_iter().collect(), counterexample_order: counterexamples.into_iter().collect(), omissions: omissions.into_iter().collect(), uncertainty: uncertainty.into_iter().collect(), negative_evidence: negative.into_iter().collect(), effect_receipts: if matches!(disposition, MultimodalKnowledgeDisposition::Completed | MultimodalKnowledgeDisposition::Partial) { vec![format!("read:local-multimodal-knowledge-world:{}", request.request_id)] } else { vec!["block:unsafe-release".into()] }, artifact, raw_data_local: request.raw_data_local, boundary: PRECLINICAL_BOUNDARY.into() }; receipt.validate()?; Ok(receipt)
}

#[cfg(test)] mod tests { use super::*; fn hash(value: &str) -> ContentHash { ContentHash::of_bytes(value.as_bytes()) } fn request() -> MultimodalKnowledgeRequest { let h=hash("multimodal-knowledge"); let claim=|id: &str, study: &str, modality: &str| MultimodalKnowledgeClaim { claim_id:id.into(), study_id:study.into(), modality:modality.into(), semantic_profile:"profile:v1".into(), subject:"organoid".into(), predicate:"expresses".into(), object:"marker".into(), evidence_digest:Some(h.clone()), provenance_digest:Some(h.clone()), comparable:true, state:EvidenceState::Supported, boundary:PRECLINICAL_BOUNDARY.into() }; MultimodalKnowledgeRequest { request_id:"request:multimodal-knowledge".into(), claims:vec![claim("claim:a","study:a","imaging"),claim("claim:b","study:b","omics")], required_studies:vec!["study:a".into(),"study:b".into()], required_modalities:vec!["imaging".into(),"omics".into()], replay_identity:h, policy_allow:true, protected_closure:true, raw_data_local:true, boundary:PRECLINICAL_BOUNDARY.into() } } #[test] fn manifest_is_a1(){assert_eq!(multimodal_knowledge_representation_inference_engine_manifest().autonomy_tier,AutonomyTier::A1);} #[test] fn complete_is_completed(){assert_eq!(infer_multimodal_knowledge_representation(&request()).unwrap().disposition,MultimodalKnowledgeDisposition::Completed);} #[test] fn missing_modality_is_partial(){let mut v=request();v.required_modalities.push("spatial".into());assert_eq!(infer_multimodal_knowledge_representation(&v).unwrap().disposition,MultimodalKnowledgeDisposition::Partial);} #[test] fn incomparable_is_partial(){let mut v=request();v.claims[0].comparable=false;assert_eq!(infer_multimodal_knowledge_representation(&v).unwrap().disposition,MultimodalKnowledgeDisposition::Partial);} #[test] fn unknown_is_partial(){let mut v=request();v.claims[0].state=EvidenceState::Unknown;assert_eq!(infer_multimodal_knowledge_representation(&v).unwrap().disposition,MultimodalKnowledgeDisposition::Partial);} #[test] fn policy_is_denied(){let mut v=request();v.policy_allow=false;assert_eq!(infer_multimodal_knowledge_representation(&v).unwrap().disposition,MultimodalKnowledgeDisposition::Denied);} #[test] fn digest_is_stable(){let r=infer_multimodal_knowledge_representation(&request()).unwrap();assert_eq!(r.digest().unwrap(),r.digest().unwrap());} }
